"""Independent reference model: LPM + image validator + image lookup (from PROTOCOL.md)."""
import json

M64 = (1 << 64) - 1
BMP_NULL = 4194303

def norm(addr, ln):
    v = int(addr, 16)
    if ln == 0:
        return 0
    return (v >> (128 - ln)) << (128 - ln)

def split(v):
    return (v >> 64) & M64, v & M64

class Fib:
    def __init__(self):
        self.p = {}   # (len, value) -> hop
    def put(self, addr, ln, hop):
        self.p[(ln, norm(addr, ln))] = hop
    def lpm(self, addr):
        v = int(addr, 16)
        for ln in range(128, -1, -1):
            key = (ln, norm(addr, ln))
            if key in self.p:
                return self.p[key]
        return None

# ------------------------------------------------------------------ image ----

def owner(origin):
    return {0: 16, 16: 64, 64: 128}[origin]

def bits128(v, d, n):
    if n <= 0:
        return 0
    return (v >> (128 - d - n)) & ((1 << n) - 1)

def top(v, ln):
    if ln <= 0:
        return 0
    return (v >> (128 - ln)) << (128 - ln)

