                        raise Bad('ni level')
            if typ == 1:
                if rec_bits(rec, 127, 1):
                    raise Bad('reserved')
                seen = False
                last = -1
                for k in range(2):
                    raw = rec_bits(rec, 63 + 32 * k, 32)
