                        raise Bad('child key order')
                    last = key
                    if depth + 6 > mx:
                        raise Bad('child beyond owner')
                    chi = reghi
                    clo = reglo
                    if depth + 6 <= 64:
                        chi |= key << (64 - depth - 6)
                    else:
                        clo |= key << (128 - depth - 6)
