// Public CLI entry point: reads the fixed wire protocol produced by run.py and
// emits one JSON response.
//
// Live state per case:
//   * ScampTrieDynamic  - the supplied live insertion/mapping core,
//   * Fib               - the exact live FIB model (distinct normalised
//                         prefixes, last write wins) used by query and by the
//                         compact image exporter,
//   * MemoryImage       - the currently loaded packed image.
#include "scamptrie_dynamic.h"
#include "image_io.hpp"
#include "fib.hpp"
#include "utils/mem_init.h"

#include <iostream>
#include <memory>
#include <stdexcept>
#include <vector>
#include <sys/wait.h>
#include <cstdlib>

int main() {
    try {
        std::ios::sync_with_stdio(false);
        std::cin.tie(nullptr);
        size_t cases;
        std::cin >> cases;
        std::cout << "{\"results\":[";
        for (size_t c = 0; c < cases; ++c) {
            if (c) std::cout << ',';
            auto live = std::unique_ptr<ScampTrieDynamic>(new ScampTrieDynamic());
            live->set_insert_prefix_timing_enabled(false);
            Fib fib;
            MemoryImage loaded;
            std::vector<nexthop_t> answers;
            std::vector<ImageData> saved;
            std::vector<bool> loads;
            size_t count;
            std::cin >> count;
            for (size_t i = 0; i < count; ++i) {
                char op;
                std::cin >> op;
                if (op == 'P') {
                    auto ip = read_ip();
                    unsigned len;
                    uint64_t hop;
                    std::cin >> len >> hop;
                    if (len > 128 || hop > 4194302ull) throw std::runtime_error("route fields");
                    fib.put((uint8_t)len, ip.hi, ip.lo, (uint32_t)hop);
                    // Keep the supplied live core in step with the FIB; its
                    // answer path is not used by the responses.
                    (void)live->insert_prefix(ip, (uint8_t)len, (nexthop_t)hop);
                } else if (op == 'Q' || op == 'I') {
                    size_t n;
                    std::cin >> n;
                    for (size_t j = 0; j < n; ++j) {
                        auto ip = read_ip();
                        if (op == 'Q') {
                            uint32_t hop = 0;
                            answers.push_back(fib.lpm(ip.hi, ip.lo, hop)
                                                  ? (nexthop_t)hop : LPM_INVALID_NH);
                        } else {
                            answers.push_back(loaded.lookup(ip));
                        }
                    }
                } else if (op == 'S') {
                    // Detached, compact snapshot of the complete live FIB.
                    auto exporter = std::unique_ptr<MemInit>(new MemInit(live.get(), fib));
                    saved.push_back(exporter->capture());
                } else if (op == 'R') {
                    size_t id;
                    std::cin >> id;
                    if (id >= saved.size()) throw std::runtime_error("saved index");
                    loads.push_back(loaded.load(saved[id]));
                } else if (op == 'L') {
                    auto d = image_read_wire();
                    loads.push_back(loaded.load(d));
                } else {
                    throw std::runtime_error("wire opcode");
                }
            }
            if (!std::cin) throw std::runtime_error("wire exhausted");
            std::cout << "{\"answers\":[";
            for (size_t i = 0; i < answers.size(); ++i) {
                if (i) std::cout << ',';
                if (answers[i] == LPM_INVALID_NH) std::cout << "null";
                else std::cout << answers[i];
            }
            std::cout << "],\"snapshots\":[";
            for (size_t i = 0; i < saved.size(); ++i) {
                if (i) std::cout << ',';
                image_write_json(saved[i]);
            }
            std::cout << "],\"loads\":[";
            for (size_t i = 0; i < loads.size(); ++i) {
                if (i) std::cout << ',';
                std::cout << (loads[i] ? "true" : "false");
            }
            std::cout << "]}";
        }
        std::cout << "]}\n";
        std::cout.flush();
        if (const char* feed = std::getenv("SCAMP_FEED_PID")) {
            int status;
            waitpid(std::strtol(feed, nullptr, 10), &status, 0);
        }
        return 0;
    } catch (const std::exception& e) {
        std::cerr << e.what() << '\n';
        return 1;
    }
}

nexthop_t MemoryImage::walk(int idx, uint64_t cursor) const {
    const ImageNode& n = nodes_[idx];
    if (n.type == 4 || n.type == 5) {
        int best_l = -1;
        uint32_t best_hop = 0;
        for (size_t k = 0; k < n.inlines.size(); ++k) {
            const ImageNode::Pfx& p = n.inlines[k];
            bool m = (p.l == 0) ? true : ((cursor >> (64 - p.l)) == (p.frag >> (64 - p.l)));
            if (m && (int)p.l > best_l) { best_l = p.l; best_hop = p.hop; }
        }
        if (best_l >= 0) return best_hop;
        return (n.bmp == IMAGE_BMP_NULL) ? LPM_INVALID_NH : (nexthop_t)n.bmp;
    }
    const int t = (n.depth - n.origin) / 6;
    const uint64_t chunk = cursor_chunk(cursor, t);
    for (size_t k = 0; k < n.children.size(); ++k)
        if (n.children[k].key == chunk)
            return walk(slots_[n.children[k].stage][n.children[k].cell], cursor);
    if (n.type == 3 && ((n.bulk_bitmap >> chunk) & 1ull)) {
        int rank = __builtin_popcountll(n.bulk_bitmap & ((1ull << chunk) - 1ull));
        uint32_t cell = n.bulk_base + 2u * (uint32_t)rank;
        return walk(slots_[n.bulk_stage][cell], cursor);
    }
    for (int l = 5; l >= 0; --l) {
        int p = (1 << l) + (int)(chunk >> (6 - l));
        if ((n.pattern >> p) & 1ull) {
            int off = __builtin_popcountll(n.pattern & (((uint64_t)1 << p) - 1ull));
            return data_.nexthops[n.ni_base + off];
        }
    }
    return (n.bmp == IMAGE_BMP_NULL) ? LPM_INVALID_NH : (nexthop_t)n.bmp;
}
nexthop_t MemoryImage::lookup(ip6_t ip) const {
    if (!front64_.empty()) {
        int i = find_front(front64_, ip.hi);
        if (i >= 0) return walk(i, ip.lo);
    }
    if (!front16_.empty()) {
        int i = find_front(front16_, ip.hi >> 48);
        if (i >= 0) return walk(i, ip.hi << 16);
    }
    if (root_idx_ >= 0) return walk(root_idx_, ip.hi);
    return LPM_INVALID_NH;
}

